// Cross-runtime codec round-trip — the JavaScript half.
//
// client/test/golden.json is generated by internal/cmd/gen-clientcodec: real
// frames, encoded by the Go protobuf runtime, each with the value it must
// decode to. This file asserts both directions against them:
//
//   Go -> JS   decodeFrame(hex) deep-equals the expected value
//   JS -> Go   encodeFrame(value) reproduces those exact bytes
//
// The second is the stronger claim, and it is why byte equality is asserted
// rather than "Go can parse what JS produced". Byte equality with the
// canonical Go encoding rules out a client that Go merely tolerates — a
// spurious default written explicitly, a field emitted twice, a length-
// delimited value where a varint belonged.
//
// The Go side of the same fixture is checked independently by
// internal/clientcodec's Ginkgo suite, which runs with `go test` and no node.
// So the fixture is validated on a clean clone; only this half needs the bench
// image (PRD FR-74, G11).

import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { decodeFrame, encodeFrame } from "../codec.gen.js";

const golden = JSON.parse(readFileSync(new URL("./golden.json", import.meta.url), "utf8"));
void fileURLToPath;

const bytes = (hex) => Uint8Array.from(hex.match(/../g) || [], (b) => parseInt(b, 16));
const hex = (u8) => Array.from(u8, (b) => b.toString(16).padStart(2, "0")).join("");

// plain turns a decoded frame into something deepEqual can compare with JSON:
// the only non-JSON value the decoder produces is a Uint8Array, for bytes.
function plain(v) {
  if (v instanceof Uint8Array) return Array.from(v);
  if (Array.isArray(v)) return v.map(plain);
  if (v && typeof v === "object") {
    const o = {};
    for (const k of Object.keys(v)) o[k] = plain(v[k]);
    return o;
  }
  return v;
}

// asWire converts the expected value back into what the encoder is handed:
// bytes fields arrive as arrays in JSON and must go in as a Uint8Array.
function asWire(v) {
  if (Array.isArray(v) && v.every((x) => typeof x === "number")) return v;
  if (Array.isArray(v)) return v.map(asWire);
  if (v && typeof v === "object") {
    const o = {};
    for (const k of Object.keys(v)) o[k] = k === "session_id" ? Uint8Array.from(v[k]) : asWire(v[k]);
    return o;
  }
  return v;
}

test("the fixture is not empty", () => {
  assert.ok(golden.length >= 10, `only ${golden.length} vectors`);
});

for (const v of golden) {
  test(`decode ${v.name}: ${v.note}`, () => {
    assert.deepEqual(plain(decodeFrame(bytes(v.hex))), v.frame);
  });

  if (v.reencode) {
    test(`encode ${v.name}`, () => {
      assert.equal(hex(encodeFrame(asWire(v.frame))), v.hex);
    });
  }
}

// --------------------------------------------------------------------------
// Properties the fixture cannot state, because they are about malformed or
// future input rather than about a correct frame.
// --------------------------------------------------------------------------

test("a locally built event round-trips through both directions", () => {
  const frame = {
    protocol_version: 1,
    session_id: Uint8Array.from({ length: 16 }, (_, i) => i),
    event: {
      client_ref: 9007199254740991, // Number.MAX_SAFE_INTEGER: the largest id the wire can carry exactly
      name: "submit.message",
      fragment_id: "composer",
      seen_server_seq: 300,
      fields: [{ key: "body", value: "héllo" }],
    },
  };
  assert.deepEqual(plain(decodeFrame(encodeFrame(frame))), plain(frame));
});

test("unknown tags of every wire type are skipped, not thrown on (FR-10)", () => {
  const base = encodeFrame({
    protocol_version: 1,
    session_id: Uint8Array.from({ length: 16 }, () => 7),
    ack: { server_seq: 3 },
  });
  const unknown = Uint8Array.from([
    0xf8, 0x03, 0x96, 0x01, // field 63, varint
    0xf2, 0x03, 0x03, 110, 101, 119, // field 62, length-delimited
    0xed, 0x03, 1, 2, 3, 4, // field 61, fixed32
    0xe1, 0x03, 1, 2, 3, 4, 5, 6, 7, 8, // field 60, fixed64
  ]);
  const both = new Uint8Array(base.length + unknown.length);
  both.set(base);
  both.set(unknown, base.length);

  const f = decodeFrame(both);
  assert.equal(f.ack.server_seq, 3);
  assert.equal(f.protocol_version, 1);
});

test("a length predicate the client does enforce rejects the frame", () => {
  // session_id is `len(this) == 16`. Seventeen bytes must not decode.
  const bad = encodeFrame({
    protocol_version: 1,
    session_id: Uint8Array.from({ length: 17 }, () => 1),
    ack: { server_seq: 1 },
  });
  assert.throws(() => decodeFrame(bad), /session_id/);
});

test("a nested length predicate is enforced too", () => {
  // Origin.source is `len(this) <= 64`. The bound is inside a submessage, so
  // this also checks that the decoder applies the table at every depth.
  const bad = encodeFrame({
    protocol_version: 1,
    session_id: Uint8Array.from({ length: 16 }, () => 1),
    patch: {
      server_seq: 1,
      patch_id: 1,
      transition_id: 1,
      state_version: 1,
      origin: { kind: 2, source: "effect:" + "x".repeat(70) },
    },
  });
  assert.throws(() => decodeFrame(bad), /source/);
});

test("predicates the client deliberately does not enforce are let through", () => {
  // `this > 0` on Ack.server_seq and the regular expression on Origin.source
  // are server-side only (docs/protocol.md §10.3). The manifest says so; this
  // asserts the manifest is telling the truth, so nobody later reads the
  // decoder as a validator it is not.
  const f = decodeFrame(
    encodeFrame({
      protocol_version: 1,
      session_id: Uint8Array.from({ length: 16 }, () => 1),
      patch: {
        server_seq: 1,
        patch_id: 1,
        transition_id: 1,
        state_version: 1,
        origin: { kind: 1, source: "NOT A VALID SOURCE" },
      },
    }),
  );
  assert.equal(f.patch.origin.source, "NOT A VALID SOURCE");
});

test("an empty frame body decodes to an empty object rather than throwing", () => {
  assert.deepEqual(decodeFrame(new Uint8Array(0)), {});
});
